import type { SharedNode } from "@repo/database/lib/sharedNodes";

export type SharedNodeSortColumn = "spaceName" | "title" | "lastModified";

export type SharedNodeSort = {
  column: SharedNodeSortColumn;
  direction: "ascending" | "descending";
};

type SortableSharedNode = Pick<SharedNode, SharedNodeSortColumn>;

export const DEFAULT_SHARED_NODE_SORT: SharedNodeSort = {
  column: "lastModified",
  direction: "descending",
};

export const getNextSharedNodeSort = ({
  currentSort,
  column,
}: {
  currentSort: SharedNodeSort;
  column: SharedNodeSortColumn;
}): SharedNodeSort => ({
  column,
  direction:
    currentSort.column === column && currentSort.direction === "descending"
      ? "ascending"
      : "descending",
});

const compareByColumn =
  (column: SharedNodeSortColumn) =>
  (left: SortableSharedNode, right: SortableSharedNode): number =>
    column === "lastModified"
      ? Date.parse(left.lastModified) - Date.parse(right.lastModified)
      : left[column].localeCompare(right[column], undefined, {
          numeric: true,
          sensitivity: "base",
        });

export const sortSharedNodes = <T extends SortableSharedNode>({
  nodes,
  sort,
}: {
  nodes: readonly T[];
  sort: SharedNodeSort;
}): T[] => {
  const compare = compareByColumn(sort.column);
  return [...nodes].sort((left, right) =>
    sort.direction === "ascending"
      ? compare(left, right)
      : compare(right, left),
  );
};
import posthog from "posthog-js";
import { stripFrontmatter } from "@repo/content-model";
import type { DGSupabaseClient } from "@repo/database/lib/client";
import type { Tables } from "@repo/database/dbTypes";
import type { SharedNode } from "@repo/database/lib/sharedNodes";
import { resolveSchemaFormat } from "@repo/utils/resolveSchemaFormat";
import { createDiscourseNodeType } from "~/components/settings/utils/accessors";
import getDiscourseNodes, {
  excludeDefaultNodes,
  type DiscourseNode,
} from "./getDiscourseNodes";
import internalError from "./internalError";
import refreshConfigTree from "./refreshConfigTree";

const SCHEMA_COLUMNS =
  "format:literal_content->>format, id, name, source_data_format:literal_content->source_data->>format, source_local_id, template_content:literal_content->>template_content";

const RESERVED_NODE_TYPE_NAMES = new Set(["Page", "Block", "Any"]);

const RESOLVE_ERROR_TYPE = "Imported node type resolution failed";
const RESOLVE_ERROR_OPERATION = "resolve-shared-node-types";

type SharedNodeSchema = Pick<
  Tables<"my_concepts">,
  "id" | "name" | "source_local_id"
> & {
  format: string | null;
  source_data_format: string | null;
  template_content: string | null;
};

// Obsidian publishes the template file as written, so its frontmatter would
// otherwise become template blocks.
export const getTemplateMarkdown = (
  templateContent: string | null | undefined,
): string | undefined => {
  const markdown = stripFrontmatter(templateContent ?? "");
  return markdown.trim() ? markdown : undefined;
};

const findOrCreateNodeType = async (
  schema: SharedNodeSchema,
): Promise<DiscourseNode | undefined> => {
  const localNodeTypes = getDiscourseNodes();
  const matchedById = localNodeTypes.find(
    (nodeType) => nodeType.type === schema.source_local_id,
  );
  if (matchedById) return matchedById;
  const matchedByName = localNodeTypes
    .filter(excludeDefaultNodes)
    .find((nodeType) => nodeType.text === schema.name);
  if (matchedByName) return matchedByName;
  if (!schema.name || !schema.source_local_id) return undefined;
  if (RESERVED_NODE_TYPE_NAMES.has(schema.name)) return undefined;

  const nodeType = await createDiscourseNodeType({
    label: schema.name,
    shortcut: "",
    format: resolveSchemaFormat({
      format: schema.format,
      sourceDataFormat: schema.source_data_format,
    }),
    template: getTemplateMarkdown(schema.template_content),
    uid: schema.source_local_id,
  });
  refreshConfigTree();
  posthog.capture("Discourse Node: Type Created From Import", {
    label: schema.name,
  });
  return nodeType;
};

export const resolveSharedNodeTypes = async ({
  client,
  sharedNodes,
}: {
  client: DGSupabaseClient;
  sharedNodes: SharedNode[];
}): Promise<Map<number, DiscourseNode>> => {
  const schemaIds = [...new Set(sharedNodes.map(({ schemaId }) => schemaId))];
  const { data, error } = await client
    .from("my_concepts")
    .select(SCHEMA_COLUMNS)
    .eq("is_schema", true)
    .eq("is_relation", false)
    .in("id", schemaIds);
  if (error) {
    internalError({
      error,
      type: RESOLVE_ERROR_TYPE,
      context: { operation: RESOLVE_ERROR_OPERATION, schemaIds },
      sendEmail: false,
    });
    return new Map<number, DiscourseNode>();
  }

  const nodeTypeBySchemaId = new Map<number, DiscourseNode>();
  for (const schema of data) {
    if (schema.id === null) continue;
    try {
      const nodeType = await findOrCreateNodeType(schema);
      if (nodeType) nodeTypeBySchemaId.set(schema.id, nodeType);
    } catch (error) {
      internalError({
        error,
        type: RESOLVE_ERROR_TYPE,
        context: {
          operation: RESOLVE_ERROR_OPERATION,
          schemaId: schema.id,
          schemaName: schema.name,
        },
        sendEmail: false,
      });
    }
  }

  return nodeTypeBySchemaId;
};

