import type { DGSupabaseClient } from "@repo/database/lib/client";
import type { LocalConceptDataInput } from "@repo/database/inputTypes";
import type { SharedNode } from "@repo/database/lib/sharedNodes";
import { orderConceptsByDependency } from "./conceptConversion";
import { sharedReferenceRid } from "./findTargetUid";
import { getErrorMessage } from "./getErrorMessage";
import { findImportedNodeUidBySourceRid } from "./importedSourceIdentity";
import { materializeSharedNode } from "./materializeSharedNode";
import { resolveSharedNodeTypes } from "./resolveSharedNodeTypes";
import { SOURCE_SLOT } from "./sourceSlot";

export type FailedSharedNodeImport = {
  sharedNode: SharedNode;
  status: "failed";
  message: string;
};

export type SharedNodeImportItem =
  | {
      sharedNode: SharedNode;
      status: "imported" | "skipped";
      pageUid: string;
      warning?: string;
    }
  | FailedSharedNodeImport;

export const isFailedSharedNodeImport = (
  item: SharedNodeImportItem,
): item is FailedSharedNodeImport => item.status === "failed";

// Normalize references to RIDs before reusing the publish/sync dependency sorter:
// bare IDs from different spaces must not collide in a shared-node batch.
const asConcept = (node: SharedNode): LocalConceptDataInput => {
  const source = node.slots?.[SOURCE_SLOT];
  return {
    source_local_id: node.rid,
    ...(source
      ? {
          local_reference_content: {
            [SOURCE_SLOT]: sharedReferenceRid(source, node.spaceUri),
          },
        }
      : {}),
  };
};

const orderSourcesFirst = (sharedNodes: SharedNode[]): SharedNode[] => {
  const nodesByRid = new Map(sharedNodes.map((node) => [node.rid, node]));
  const { ordered } = orderConceptsByDependency(sharedNodes.map(asConcept));
  return ordered.map((concept) => nodesByRid.get(concept.source_local_id!)!);
};

const discoveredSourcesToImport = async ({
  sharedNodes,
  discoveredNodes,
}: {
  sharedNodes: SharedNode[];
  discoveredNodes: SharedNode[];
}): Promise<SharedNode[]> => {
  const { missing } = orderConceptsByDependency(sharedNodes.map(asConcept));
  const discoveredByRid = new Map(
    discoveredNodes.map((node) => [node.rid, node]),
  );
  const sources: SharedNode[] = [];
  for (const rid of missing) {
    const source = discoveredByRid.get(rid);
    if (!source) continue;
    const importedUid = await findImportedNodeUidBySourceRid(rid).catch(
      () => null,
    );
    if (!importedUid) sources.push(source);
  }
  return sources;
};

export const importSharedNodes = async ({
  client,
  sharedNodes,
  discoveredNodes,
  onProgress,
}: {
  client: DGSupabaseClient;
  sharedNodes: SharedNode[];
  discoveredNodes: SharedNode[];
  onProgress: (current: number, total: number) => void;
}): Promise<SharedNodeImportItem[]> => {
  const batch = [
    ...sharedNodes,
    ...(await discoveredSourcesToImport({ sharedNodes, discoveredNodes })),
  ];
  const nodeTypesBySchemaId = await resolveSharedNodeTypes({
    client,
    sharedNodes: batch,
  });
  const items: SharedNodeImportItem[] = [];
  for (const sharedNode of orderSourcesFirst(batch)) {
    try {
      const result = await materializeSharedNode({
        client,
        sharedNode,
        nodeType: nodeTypesBySchemaId.get(sharedNode.schemaId),
      });
      items.push(
        result.success
          ? {
              sharedNode,
              status: result.action === "skipped" ? "skipped" : "imported",
              pageUid: result.pageUid,
              ...(result.warning ? { warning: result.warning } : {}),
            }
          : { sharedNode, status: "failed", message: result.error.message },
      );
    } catch (error) {
      items.push({
        sharedNode,
        status: "failed",
        message: getErrorMessage(error),
      });
    }
    onProgress(items.length, batch.length);
  }
  return items;
};
import { getSharedNodeByRid } from "@repo/database/lib/sharedNodes";
import getPageTitleByPageUid from "roamjs-components/queries/getPageTitleByPageUid";
import { readImportedSourceIdentity } from "./importedSourceIdentity";
import internalError from "./internalError";
import { getErrorMessage } from "./getErrorMessage";
import { materializeSharedNode } from "./materializeSharedNode";
import { resolveSharedNodeTypes } from "./resolveSharedNodeTypes";
import { getLoggedInClient, getSupabaseContext } from "./supabaseContext";
import { importSharedRelations } from "./importSharedRelations";
import type { DGSupabaseClient } from "@repo/database/lib/client";

export const REFRESH_ERROR_TYPE = "Imported node refresh failed";
const REFRESH_ERROR_OPERATION = "refresh-imported-node";

type RefreshImportedNodeResult = {
  status: "refreshed" | "skipped" | "failed";
  message: string;
  warning?: string;
};

// A relation published after both of its ends were imported arrives only with a later
// import or refresh. Returns a warning when some relations could not be imported.
export const importRelationsAfterRefresh = async (
  client: DGSupabaseClient,
): Promise<string | undefined> => {
  try {
    const context = await getSupabaseContext();
    if (!context)
      return "Could not import relations: could not connect to shared persistence.";
    // Skipped relations are not reported: they need not involve the refreshed node.
    const { failures } = await importSharedRelations(client, context.spaceId);
    if (failures.length === 0) return undefined;
    return failures.length === 1
      ? "1 relation could not be imported."
      : `${failures.length} relations could not be imported.`;
  } catch (error) {
    internalError({
      error,
      type: REFRESH_ERROR_TYPE,
      context: { operation: "import-relations-after-refresh" },
      sendEmail: false,
    });
    return `Could not import relations: ${getErrorMessage(error)}`;
  }
};

const joinWarnings = (...warnings: (string | undefined)[]) => {
  const present = warnings.filter((w) => w !== undefined);
  return present.length > 0 ? { warning: present.join(" ") } : {};
};

// Refresh-all passes `importRelations: false` and imports relations once at the end.
export const refreshImportedNode = async ({
  pageUid,
  force,
  importRelations = true,
}: {
  pageUid: string;
  force: boolean;
  importRelations?: boolean;
}): Promise<RefreshImportedNodeResult> => {
  try {
    const title = getPageTitleByPageUid(pageUid);
    const identity = readImportedSourceIdentity(pageUid);
    if (!identity)
      return {
        status: "failed",
        message: `"${title}" has no stored source identity, so it cannot be refreshed.`,
      };

    const client = await getLoggedInClient();
    if (!client)
      return {
        status: "failed",
        message: "Could not connect to shared persistence.",
      };

    const sharedNode = await getSharedNodeByRid({
      client,
      rid: identity.sourceNodeRid,
    });
    if (!sharedNode)
      return {
        status: "failed",
        message: `The source of "${title}" is no longer shared with your groups, so it cannot be refreshed.`,
      };

    const nodeTypesBySchemaId = await resolveSharedNodeTypes({
      client,
      sharedNodes: [sharedNode],
    });
    const result = await materializeSharedNode({
      client,
      sharedNode,
      nodeType: nodeTypesBySchemaId.get(sharedNode.schemaId),
      force,
    });
    if (!result.success) {
      internalError({
        error: new Error(result.error.message),
        type: REFRESH_ERROR_TYPE,
        context: {
          operation: REFRESH_ERROR_OPERATION,
          pageUid,
          stage: result.error.stage,
        },
        sendEmail: false,
      });
      return { status: "failed", message: result.error.message };
    }
    if (result.pageUid !== pageUid)
      return {
        status: "failed",
        message: `A different page ("${getPageTitleByPageUid(result.pageUid)}") is linked to the same source and was refreshed instead.`,
      };
    const relationWarning = importRelations
      ? await importRelationsAfterRefresh(client)
      : undefined;
    if (result.action === "skipped")
      return {
        status: "skipped",
        message: `"${sharedNode.title}" is already up to date.`,
        ...joinWarnings(relationWarning),
      };
    return {
      status: "refreshed",
      message: `Refreshed "${sharedNode.title}" from ${sharedNode.spaceName}.`,
      ...joinWarnings(result.warning, relationWarning),
    };
  } catch (error) {
    internalError({
      error,
      type: REFRESH_ERROR_TYPE,
      context: { operation: REFRESH_ERROR_OPERATION, pageUid },
      sendEmail: false,
    });
    return {
      status: "failed",
      message: `Could not refresh this page: ${getErrorMessage(error)}`,
    };
  }
};

