  lastModified: "2026-06-14T09:00:00.000Z",
};
const newer = {
  spaceName: "Alpha graph",
  title: "Claim 9",
  lastModified: "2026-06-14T15:00:00.000Z",
};
const newest = {
  spaceName: "Gamma vault",
  title: "evidence",
  lastModified: "2026-06-14T14:00:00.000-02:00",
};

