    ).toEqual({ column: "title", direction: "descending" });
  });

  it("toggles the active column between descending and ascending", () => {
    const ascending = getNextSharedNodeSort({
      currentSort: DEFAULT_SHARED_NODE_SORT,
      column: "lastModified",
