    expect(ascending).toEqual({
      column: "lastModified",
      direction: "ascending",
    });
    expect(
      getNextSharedNodeSort({ currentSort: ascending, column: "lastModified" }),
    ).toEqual(DEFAULT_SHARED_NODE_SORT);
  });
});

