import re
def edit(p, pairs, post=None):
    s=open(p).read()
    for old,new in pairs:
        assert s.count(old)==1, (p, old, s.count(old))
        s=s.replace(old,new)
    if post: s=post(s)
    open(p,'w').write(s)

def add_space(s):
    n=s.count("importNodeAssets({")
    s2=re.sub(r'(\n(\s*)sharedNode,)(?=\n)', r'\1\n\2space,', s)
    s2=s2.replace("importNodeAssets({ client, sharedNode, markdown", "importNodeAssets({ client, sharedNode, space, markdown")
    print(n, "calls;", s2.count("space,")+s2.count("space, markdown"), "space args")
    return s2

